/* ============================================================
   موسوعة الأدوية — أجسام بطاقات دفعة الأورام الثانية
   rx/rx-onco2.js   (يُحمَّل عند فتح البطاقة)
   ⚠️ محتوى تثقيفي عام وليس وصفة علاج. الجرعة والخطّة يحدّدهما فريق الأورام.
   كُتبت كل بطاقة من نشرات مفتوحة وقت الكتابة — روابطها في src.
   ============================================================ */

var RX_BODY = window.RX_BODY || {};

RX_BODY['gemcitabine'] = {
  what: {
    ar: 'الجيمسيتابين دواء كيميائي لعلاج السرطان من فصيلة مضادّات الأيض، أي أنه يشبه في تركيبه إحدى المواد الخام التي تبني بها الخلية حمضها النووي فيندسّ مكانها. لا يُصرف للبيت ولا يؤخذ بالفم: يأتي مسحوقاً يُذاب ثم يُعطى بالتنقيط في الوريد داخل مركز علاج الأورام على يد طبيب أو ممرّض، عبر قنية في الذراع أو خطّ وريدي مركزي. ويُعطى غالباً مع دواء كيميائي آخر ضمن خطّة يضعها فريق الأورام، فالمريض لا يختاره ولا يضبطه، لكنه يحتاج أن يعرف ما يراقبه في نفسه بين الجلسات.',
    en: 'Gemcitabine is a cancer chemotherapy from the antimetabolite class, meaning its structure resembles one of the raw materials a cell uses to build its DNA, so it slips into that place. It is not dispensed for home and is not taken by mouth: it comes as a powder that is dissolved and given by drip into a vein in a cancer treatment centre by a doctor or nurse, through a cannula in the arm or a central line. It is usually given with another chemotherapy drug in a plan set by the oncology team, so the patient neither chooses nor adjusts it, but needs to know what to watch for in themselves between sessions.'
  },
  why: {
    ar: 'يُستعمل في علاج عدّة أنواع من السرطان: سرطان البنكرياس المنتشر، وسرطان الرئة من نوع الخلايا غير الصغيرة حين ينتشر ولا تنفع معه الجراحة، وسرطان الثدي الذي لم يتحسّن أو ساء بعد أدوية أخرى، وسرطان المبيض الذي عاد بعد انتهاء علاج سابق. ويُستعمل كذلك في سرطان المثانة وسرطان القنوات الصفراوية. وفي أغلب هذه الحالات يُقرن بدواء آخر كالسيسبلاتين أو الكاربوبلاتين أو الباكليتاكسيل. واختيار الخطّة وعدد الجلسات قرار فريق الأورام بحسب نوع الورم ومرحلته وحالة المريض العامة.',
    en: 'It is used to treat several kinds of cancer: pancreatic cancer that has spread, non-small cell lung cancer that has spread and cannot be treated with surgery, breast cancer that has not improved or has worsened after other medicines, and ovarian cancer that has come back after an earlier treatment ended. It is also used in bladder cancer and cancer of the bile ducts. In most of these cases it is paired with another drug such as cisplatin, carboplatin or paclitaxel. Choosing the plan and the number of sessions is the decision of the oncology team, according to the type and stage of the tumour and the general condition of the patient.'
  },
  how: {
    ar: 'الخلية السرطانية تنقسم بسرعة، وكل انقسام يحتاج نسخة جديدة من الحمض النووي. يدخل الجيمسيتابين الخلية فيتحوّل إلى صورته الفعّالة، ثم يُدمج في سلسلة الحمض النووي وهي تُبنى كأنه قطعة سليمة، فيتعطّل البناء ولا تكتمل النسخة، فتموت الخلية أو تعجز عن التكاثر. ولأنه يضرب الخلايا السريعة الانقسام عموماً، يصيب معها بعض الخلايا السليمة السريعة مثل خلايا نخاع العظم التي تصنع الدم وخلايا بطانة الفم وبصيلات الشعر، ومن هنا تأتي أغلب آثاره الجانبية.',
    en: 'A cancer cell divides quickly, and every division needs a new copy of its DNA. Gemcitabine enters the cell and is converted into its active form, then it is built into the DNA chain as it is being assembled as though it were a normal piece, so construction stalls and the copy is never completed, and the cell dies or cannot multiply. Because it hits rapidly dividing cells in general, it also affects some fast-dividing healthy cells, such as the bone marrow cells that make blood, the cells lining the mouth and the hair follicles, and that is where most of its side effects come from.'
  },
  effects: {
    ar: 'من آثاره الشائعة: غثيان وقيء، وإسهال أو إمساك، وفقدان الشهية، وتقرّحات في الفم، وصداع وآلام في العضلات، وأعراض تشبه الإنفلونزا، وتعب. وقد يتساقط الشعر، ويظهر ألم أو احمرار في موضع الحقن، ووخز أو حرقة في اليدين والقدمين. وأهمّ أثر غير ظاهر هو انخفاض كريات الدم: البيضاء فتضعف المناعة، والحمراء فيظهر شحوب وضيق نفس، والصفائح فيسهل التكدّم والنزف. ولهذا تُجرى تحاليل دم قبل الجلسات، وقد تؤجَّل جلسة إن انخفضت الكريات، وهذا إجراء حماية لا فشل في العلاج.',
    en: 'Its common effects include nausea and vomiting, diarrhoea or constipation, loss of appetite, mouth sores, headache and muscle aches, flu-like symptoms, and tiredness. Hair may fall out, there may be pain or redness at the injection site, and tingling or burning in the hands and feet. The most important hidden effect is a fall in blood cells: white cells, so immunity weakens; red cells, so pallor and breathlessness appear; and platelets, so bruising and bleeding come easily. That is why blood tests are done before sessions, and a session may be postponed if the counts fall, which is a protective step, not a failure of treatment.'
  },
  warning: {
    ar: 'اتصل بخطّ فريق الأورام فوراً، ولو ليلاً، عند أي علامة عدوى: حرارة سبعة وثلاثين ونصف درجة أو أكثر، أو أقلّ من ستّ وثلاثين، أو قشعريرة أو التهاب حلق أو سعال، فالمناعة منخفضة والعدوى قد تتدهور بسرعة. واذهب إلى الطوارئ عند: ضيق نفس مفاجئ أو صفير، أو تورّم في الوجه أو الحلق، أو طفح منتشر مع تقشّر أو فقاعات، أو نزف غير معتاد أو براز فيه دم أو سعال بدم، أو اصفرار العينين وبول داكن، أو تغيّر واضح في كمية البول، أو تورّم الساقين، أو خفقان غير منتظم، أو نوبة تشنّج أو ارتباك أو تغيّر مفاجئ في النظر.',
    en: 'Call the oncology team line at once, even at night, with any sign of infection: a temperature of thirty-seven and a half degrees or more, or below thirty-six, or chills, a sore throat or a cough, because immunity is low and infection can worsen quickly. Go to the emergency department for: sudden breathlessness or wheezing, swelling of the face or throat, a spreading rash with peeling or blisters, unusual bleeding, blood in the stool or coughed-up blood, yellow eyes with dark urine, a clear change in the amount of urine, swollen legs, an irregular heartbeat, or a seizure, confusion or a sudden change in vision.'
  },
  interact: {
    ar: 'أخبر فريق الأورام بكل ما تتناوله، بما في ذلك الفيتامينات والأعشاب والمكمّلات والأدوية التي تُصرف بلا وصفة، فالنشرة تطلب ذلك صراحة لأن أدوية السرطان قد تتعارض مع أدوية أخرى ومع بعض الأطعمة والمشروبات، وتذكر النشرة البريطانية عصير الجريب فروت مثالاً فاسأل عنه قبل تناوله. وأخبر الطبيب إن كنت تتلقّى علاجاً إشعاعياً الآن أو تلقّيته سابقاً، فهذا ممّا تنصّ النشرة على ذكره قبل البدء. ولا تأخذ أي لقاح إلا بعد سؤال الفريق، واللقاحات الحيّة ممنوعة أثناء العلاج ولفترة بعده قد تمتدّ سنة.',
    en: 'Tell the oncology team about everything you take, including vitamins, herbs, supplements and non-prescription medicines, as the leaflet explicitly asks, because cancer drugs can interact with other medicines and with some foods and drinks; the British leaflet gives grapefruit juice as an example, so ask before having it. Tell the doctor if you are receiving radiotherapy now or have had it before, as the leaflet says this must be mentioned before starting. Do not have any vaccine without asking the team, and live vaccines are not allowed during treatment and for a period afterwards that may last up to a year.'
  },
  avoid: {
    ar: 'لا يُعطى لمن أصابته حساسية سابقة منه. ويُجرى اختبار حمل قبل البدء لأنه قد يؤذي الجنين، وعلى المرأة استعمال وسيلة منع حمل فعّالة أثناء العلاج ولستّة أشهر بعد آخر جلسة، وعلى الرجل وشريكته ذلك لثلاثة أشهر بعدها. ولا ترضعي أثناء العلاج ولأسبوع بعد آخر جلسة. وقد يُنقص خصوبة الرجل، فيُناقش ذلك مع الطبيب قبل البدء إن كانت الخصوبة مهمّة. ومن عنده مرض في الكبد، بما فيه التهاب الكبد الفيروسي، أو مرض في الكلى، عليه أن يخبر الطبيب لأن ذلك يغيّر الخطّة والمتابعة.',
    en: 'It is not given to anyone who has had an allergy to it before. A pregnancy test is done before starting because it may harm an unborn baby, and a woman must use effective contraception during treatment and for six months after the last session, and a man and his partner must do so for three months afterwards. Do not breastfeed during treatment and for a week after the last session. It may reduce male fertility, so this is discussed with the doctor before starting if fertility matters. Anyone with liver disease, including viral hepatitis, or kidney disease must tell the doctor, because this changes the plan and the monitoring.'
  },
  updated: '2026-09-11',
  src: [
    'https://medlineplus.gov/druginfo/meds/a696019.html',
    'https://www.cancerresearchuk.org/about-cancer/treatment/drugs/gemcitabine'
  ]
};

RX_BODY['fludarabine'] = {
  what: {
    ar: 'الفلودارابين دواء كيميائي من فصيلة مضادّات الأيض يُستعمل في سرطانات الدم والجهاز اللمفاوي. يُعطى غالباً بالتنقيط في الوريد داخل المستشفى عبر قنية أو خطّ مركزي، وتوجد منه أقراص تُبلع كاملة مع الماء بحسب تعليمات الفريق. أثره الأبرز أنه يُضعف المناعة، والنشرة الرسمية تحذّر من عدوى انتهازية خطيرة قد تكون قاتلة، ومن فقر دم يهاجم فيه الجسم كرياته الحمراء. ولهذا يرافقه عادةً نظام متابعة دقيق بالتحاليل، وتعليمات خاصة بأي نقل دم قد يحتاجه المريض.',
    en: 'Fludarabine is an antimetabolite chemotherapy used in cancers of the blood and lymphatic system. It is usually given by drip into a vein in hospital through a cannula or central line, and there are also tablets that are swallowed whole with water according to the team instructions. Its most notable effect is that it weakens immunity, and the official label warns of serious opportunistic infections that can be fatal, and of an anaemia in which the body attacks its own red cells. So it usually comes with close monitoring through blood tests, and special instructions for any blood transfusion the patient may need.'
  },
  why: {
    ar: 'يُستعمل أساساً في ابيضاض الدم اللمفاوي المزمن من نوع الخلايا البائية، وتنصّ النشرة الأمريكية على استعماله لمن لم يستجب لعلاج سابق أو عاد مرضه بعده. وتذكر النشرة البريطانية استعماله كذلك في بعض أنواع اللمفوما، وهي سرطانات تنشأ في الخلايا اللمفاوية. وقد يُعطى وحده أو ضمن خطّة مع أدوية أخرى. واختياره قرار طبيب أمراض الدم والأورام بحسب نوع المرض ومرحلته وحالة المريض، وخصوصاً وظائف كليتيه، لأن ضعف الكلى يغيّر طريقة إعطائه وقد يمنعه تماماً.',
    en: 'It is used mainly in B-cell chronic lymphocytic leukaemia, and the American label specifies it for people who did not respond to an earlier treatment or whose disease came back after it. The British leaflet also mentions its use in some types of lymphoma, cancers that arise in lymphocytes. It may be given alone or in a plan with other drugs. Choosing it is the decision of the haematology and oncology doctor according to the type and stage of the disease and the condition of the patient, especially kidney function, because weak kidneys change the way it is given and may rule it out entirely.'
  },
  how: {
    ar: 'يدخل الدواء الجسم بصورة غير فعّالة، ثم يتحوّل داخل الخلية إلى مادّة فعّالة تعطّل الإنزيمات التي تنسخ الحمض النووي وتصنع مواد بنائه، فتعجز الخلية عن الانقسام وعن إصلاح نفسها فتموت، وهذا ما يوقف تكاثر الخلايا الخبيثة. ولأنه يضرب الخلايا التي تنقسم، يصيب معها خلايا نخاع العظم التي تصنع كريات الدم البيضاء والحمراء والصفائح، فتضعف المناعة ويظهر فقر دم وميل إلى النزف والتكدّم. ولهذا تُفحص تعداد الدم بانتظام قبل الجلسات وبينها.',
    en: 'The drug enters the body in an inactive form, then inside the cell it is converted into an active substance that blocks the enzymes which copy DNA and make its building blocks, so the cell can neither divide nor repair itself and dies, which is what stops the malignant cells multiplying. Because it hits dividing cells, it also affects the bone marrow cells that make white cells, red cells and platelets, so immunity weakens and anaemia and a tendency to bleed and bruise appear. That is why blood counts are checked regularly before and between sessions.'
  },
  effects: {
    ar: 'من آثاره الشائعة: ضعف المناعة وكثرة العدوى، وفقر دم يظهر شحوباً وضيق نفس، وسهولة التكدّم والنزف بسبب نقص الصفائح، وتعب وضعف عام، وحمّى، وغثيان وقيء، وإسهال، وفقدان شهية، وسعال أو صعوبة في التنفّس. ومن الآثار الأقلّ شيوعاً والأخطر التي تذكرها النشرة: فقر دم انحلالي مناعي يهاجم فيه الجهاز المناعي كريات الدم الحمراء فيكسرها، وقد يحدث بعد جلسة واحدة أو أكثر ويكون مهدّداً للحياة أحياناً، وعدوى فيروسية كامنة قد تنشط من جديد.',
    en: 'Its common effects include weakened immunity and frequent infections, anaemia showing as pallor and breathlessness, easy bruising and bleeding from low platelets, tiredness and general weakness, fever, nausea and vomiting, diarrhoea, loss of appetite, and cough or difficulty breathing. Among the less common and more serious effects the label mentions are autoimmune haemolytic anaemia, in which the immune system attacks and breaks down red blood cells, which may occur after one or more sessions and is sometimes life-threatening, and dormant viral infections that may become active again.'
  },
  warning: {
    ar: 'اتصل بالفريق فوراً، ولو ليلاً، عند أي علامة عدوى: حرارة سبعة وثلاثين ونصف درجة أو أكثر، أو أقلّ من ستّ وثلاثين، أو قشعريرة أو سعال. واذهب إلى الطوارئ عند: ارتباك أو هياج أو نوبة تشنّج أو ضعف مفاجئ في النظر، فالنشرة تحذّر من أذى عصبي شديد؛ أو شحوب وتعب شديد وضيق نفس يظهر فجأة، فقد يكون تكسّراً في كريات الدم الحمراء؛ أو ضيق نفس وسعال جديد؛ أو نزف أو تكدّم غير معتاد. وفي الأيام الأولى قد يتحلّل الورم بسرعة فيُرهق الجسم، ولهذا يراقب الفريق التحاليل عن قرب، فلا تفوّت أي موعد تحليل.',
    en: 'Call the team at once, even at night, with any sign of infection: a temperature of thirty-seven and a half degrees or more, or below thirty-six, or chills or a cough. Go to the emergency department for: confusion, agitation, a seizure or sudden loss of vision, because the label warns of severe nerve damage; sudden pallor, severe tiredness and breathlessness, which may mean red blood cells are breaking down; breathlessness with a new cough; or unusual bleeding or bruising. In the first days the tumour may break down quickly and strain the body, which is why the team watches the blood tests closely, so do not miss any test appointment.'
  },
  interact: {
    ar: 'أهمّ تعارض تنصّ عليه النشرة: لا يُجمع مع البنتوستاتين، وهو دواء آخر لابيضاض الدم، فقد أدّى الجمع بينهما في دراسة إلى تسمّم رئوي قاتل بنسبة غير مقبولة. وأي نقل دم يحتاجه المريض يجب أن يكون دماً معالجاً بالإشعاع، لأن خلايا المتبرّع الحيّة قد تهاجم جسم المريض ضعيف المناعة فيما يُسمّى داء الطعم ضدّ المضيف، فأخبر أي مستشفى أو بنك دم تتعامل معه أنك تلقّيت هذا الدواء. ولا لقاحات حيّة أثناء العلاج ولفترة بعده قد تصل سنة. وأخبر الفريق بكل دواء وعشبة ومكمّل تتناوله.',
    en: 'The most important interaction the label specifies: it is not combined with pentostatin, another leukaemia drug, because the combination led in a study to an unacceptable rate of fatal lung toxicity. Any blood transfusion the patient needs must be irradiated blood, because the living donor cells can attack the body of a patient with weak immunity in what is called graft-versus-host disease, so tell any hospital or blood bank you deal with that you have received this drug. No live vaccines during treatment and for a period afterwards that may reach a year. Tell the team about every medicine, herb and supplement you take.'
  },
  avoid: {
    ar: 'لا يُعطى في ضعف الكلى الشديد بنصّ النشرة، ويحتاج الضعف الأخفّ تعديلاً يقرّره الطبيب. وقد يؤذي الجنين، فتتجنّب المرأة الحمل أثناء العلاج ولستّة أشهر على الأقل بعده باستعمال وسيلة فعّالة، ويناقش الرجل منع الحمل مع الفريق كذلك. ولا ترضعي أثناء العلاج. ويوقف الطبيب الدواء إن ظهر تكسّر في كريات الدم الحمراء. ومن عنده عدوى نشطة أو تاريخ مع عدوى فيروسية كامنة عليه أن يخبر الفريق قبل البدء، لأن ضعف المناعة قد يعيد نشاطها.',
    en: 'By the label, it is not given in severe kidney impairment, and milder impairment needs an adjustment decided by the doctor. It may harm an unborn baby, so a woman avoids pregnancy during treatment and for at least six months afterwards using an effective method, and a man discusses contraception with the team as well. Do not breastfeed during treatment. The doctor stops the drug if red blood cells start breaking down. Anyone with an active infection or a history of dormant viral infection must tell the team before starting, because weakened immunity may reactivate them.'
  },
  updated: '2026-09-11',
  src: [
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8039c2e3-ffe5-3997-e053-2991aa0ad9d0',
    'https://www.cancerresearchuk.org/about-cancer/treatment/drugs/fludarabine'
  ]
};

RX_BODY['mercaptopurine'] = {
  what: {
    ar: 'الميركابتوبيورين دواء كيميائي من فصيلة مضادّات البيورين، يؤخذ بالفم أقراصاً أو شراباً. وهو من الأدوية الكيميائية القليلة التي يأخذها المريض في بيته بنفسه لفترة طويلة ضمن خطّة علاج ابيضاض الدم، فيمسك علبته بيده ويحتاج أن يعرف قواعدها. تنصح النشرة البريطانية بأخذه بطريقة ثابتة، مع الطعام أو بدونه كما بدأت، وبفصله عن الحليب ومشتقّاته بفارق زمني يشرحه الصيدلي.',
    en: 'Mercaptopurine is a chemotherapy drug from the purine antagonist class, taken by mouth as tablets or a liquid. It is one of the few chemotherapy drugs a patient takes at home by themselves for a long period as part of a leukaemia treatment plan, so they hold the box in their hand and need to know its rules. The British leaflet advises taking it in a consistent way, with or without food as you started, and separating it from milk and dairy products by a time gap that the pharmacist explains.'
  },
  why: {
    ar: 'يُستعمل أساساً في علاج ابيضاض الدم اللمفاوي الحادّ، وحده أو مع أدوية كيميائية أخرى، وهو من ركائز المرحلة الطويلة من علاجه عند الأطفال والكبار. وتذكر النشرة البريطانية استعماله كذلك في ابيضاض الدم النقوي الحادّ من نوع سليفات النقي، وهو نوع نادر. وتذكر مدلاين بلس أن الأطباء يستعملونه أحياناً في داء كرون والتهاب القولون التقرّحي، وهو استعمال خارج الترخيص الأصلي يقرّره طبيب الجهاز الهضمي لتهدئة المناعة التي تهاجم الأمعاء، ويحتاج فيه المريض المتابعة نفسها بالتحاليل.',
    en: 'It is used mainly to treat acute lymphoblastic leukaemia, alone or with other chemotherapy drugs, and it is one of the mainstays of the long phase of its treatment in children and adults. The British leaflet also mentions its use in acute promyelocytic leukaemia, a rare type of acute myeloid leukaemia. MedlinePlus notes that doctors sometimes use it in Crohn disease and ulcerative colitis, an off-label use decided by a gastroenterologist to calm the immune response attacking the gut, in which the patient needs the same monitoring with blood tests.'
  },
  how: {
    ar: 'يشبه الميركابتوبيورين في تركيبه البيورينات، وهي من المواد الأساسية التي تبني بها الخلية حمضها النووي. فيحلّ محلّها داخل الخلية ويمنعها من صنع الحمض النووي وإصلاحه، فتعجز الخلايا السرطانية عن النموّ والتكاثر. ويفكّكه الجسم بإنزيمات، أهمّها إنزيمان يُعرفان باختصارهما تي بي إم تي ونودت خمسة عشر. وبعض الناس يرثون ضعفاً في أحدهما أو كليهما، فيتراكم الدواء الفعّال في خلاياهم ويهبط تعداد الدم عندهم هبوطاً شديداً بالمقادير المعتادة، ولهذا قد يطلب الطبيب فحصاً وراثياً لهما.',
    en: 'Mercaptopurine resembles the purines in structure, which are among the basic materials a cell uses to build its DNA. It takes their place inside the cell and stops it from making and repairing DNA, so cancer cells cannot grow and multiply. The body breaks it down with enzymes, the most important being two known by their abbreviations TPMT and NUDT15. Some people inherit a weakness in one or both, so the active drug builds up in their cells and their blood count falls severely at the usual amounts, which is why the doctor may order a genetic test for them.'
  },
  effects: {
    ar: 'أكثر آثاره شيوعاً انخفاض كريات الدم: البيضاء فتكثر العدوى، والحمراء فيظهر فقر الدم، والصفائح فيظهر تكدّم ونزف من اللثة. ومن الآثار الأخرى: غثيان وقيء، واسمرار الجلد، وتساقط الشعر، وطفح جلدي. ويصبح الجلد أكثر حساسية لأشعة الشمس، فيُنصح بتقليل التعرّض واستعمال واقٍ عالي الحماية وملابس ساترة. وقد يرتفع أثره على الكبد فتظهر تغيّرات في تحاليله دون أعراض، ولهذا تُجرى تحاليل الدم والكبد بانتظام في بداية العلاج ثم على فترات أطول.',
    en: 'Its most common effect is a fall in blood cells: white cells, so infections become frequent; red cells, so anaemia appears; and platelets, so bruising and bleeding gums appear. Other effects include nausea and vomiting, darkening of the skin, hair loss and rash. The skin becomes more sensitive to sunlight, so reducing exposure and using high-protection sunscreen and covering clothes is advised. It may also affect the liver, with changes in liver tests before any symptoms, which is why blood and liver tests are done regularly at the start of treatment and then at longer intervals.'
  },
  warning: {
    ar: 'اتصل بالفريق فوراً عند أي علامة عدوى: حرارة سبعة وثلاثين ونصف درجة أو أكثر، أو أقلّ من ستّ وثلاثين، أو قشعريرة أو التهاب حلق. واتصل في اليوم نفسه أو اذهب إلى الطوارئ عند: اصفرار الجلد أو العينين، أو انتفاخ البطن أو ألم تحت الأضلاع اليمنى، أو حكّة شديدة مع فقدان شهية، فهذه علامات أذى الكبد؛ أو ألم شديد في البطن مع حمّى، وقد يكون التهاباً في البنكرياس؛ أو تورّم الوجه؛ أو نزف أو تكدّم غير معتاد؛ أو شحوب وضيق نفس. ومن يأخذه لأمراض الأمعاء يراجع طبيبه عند حمّى مستمرّة مع تعرّق ليلي ونقص وزن غير مفسَّر.',
    en: 'Call the team at once with any sign of infection: a temperature of thirty-seven and a half degrees or more, or below thirty-six, or chills or a sore throat. Call the same day or go to the emergency department for: yellow skin or eyes, a swollen abdomen or pain under the right ribs, or severe itching with loss of appetite, which are signs of liver injury; severe abdominal pain with fever, which may be inflammation of the pancreas; swelling of the face; unusual bleeding or bruising; or pallor and breathlessness. Anyone taking it for bowel disease should see their doctor for persistent fever with night sweats and unexplained weight loss.'
  },
  interact: {
    ar: 'أخطر تعارضاته مع الألوبيورينول والفيبوكسوستات، وهما دواءان يخفّضان حمض اليوريك: يمنعان تفكيكه فيرتفع مستواه إلى حدّ خطير ما لم يخفّض الطبيب مقداره تخفيضاً كبيراً، فلا تبدأ أيّاً منهما دون علم فريق الأورام. ويُضعف أثر الوارفارين المميّع فيحتاج فحص سيولة الدم متابعةً أقرب. ومركّبات الأمينوساليسيلات كالميسالازين والسلفاسالازين، الشائعة في أمراض الأمعاء، تزيد هبوط تعداد الدم. ويذكر المصدر كذلك الترايميثوبريم مع السلفاميثوكسازول، وأدوية كيميائية أخرى. ولا لقاحات حيّة أثناء العلاج ولفترة بعده.',
    en: 'Its most dangerous interactions are with allopurinol and febuxostat, drugs that lower uric acid: they stop it being broken down, so its level rises dangerously unless the doctor cuts the amount substantially, so do not start either without the oncology team knowing. It weakens the blood thinner warfarin, so blood clotting tests need closer monitoring. Aminosalicylates such as mesalazine and sulfasalazine, common in bowel disease, increase the fall in blood counts. The source also lists trimethoprim with sulfamethoxazole and other chemotherapy drugs. No live vaccines during treatment and for a period afterwards.'
  },
  avoid: {
    ar: 'قد يؤذي الجنين، فعلى من يأخذه استعمال وسيلة منع حمل فعّالة أثناء العلاج ولثلاثة أشهر على الأقل بعده بحسب النشرة البريطانية. ولا ترضعي أثناء العلاج ولأسبوع بعد آخر جرعة. وقد يُضعف خصوبة الرجل والمرأة. ومن عُرف عنده نقص وراثي في إنزيمَي تي بي إم تي أو نودت خمسة عشر يحتاج تعديلاً كبيراً يقرّره المختصّ. ويخبر الطبيب من عنده مرض في الكبد أو الكلى أو عدوى نشطة. وتذكر النشرة ورماً لمفاوياً نادراً عدوانياً في الكبد والطحال سُجّل عند مرضى عولجوا به من أمراض الأمعاء الالتهابية.',
    en: 'It may harm an unborn baby, so anyone taking it must use effective contraception during treatment and for at least three months afterwards according to the British leaflet. Do not breastfeed during treatment and for a week after the last dose. It may reduce fertility in men and women. Anyone known to have an inherited deficiency of the TPMT or NUDT15 enzymes needs a major adjustment decided by a specialist. Anyone with liver or kidney disease or an active infection must tell the doctor. The label mentions a rare, aggressive lymphoma of the liver and spleen reported in patients treated for inflammatory bowel disease.'
  },
  updated: '2026-09-11',
  src: [
    'https://medlineplus.gov/druginfo/meds/a682653.html',
    'https://www.cancerresearchuk.org/about-cancer/treatment/drugs/mercaptopurine',
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c3b5b8b0-bc5c-4ce9-bbdc-febba60c2658'
  ]
};

RX_BODY['tioguanine'] = {
  what: {
    ar: 'التيوجوانين، ويُكتب أيضاً الثيوغوانين، دواء كيميائي يؤخذ بالفم أقراصاً، من نظائر البيورين، وهي فصيلة تشبه موادّ بناء الحمض النووي. هو قريب في عمله من الميركابتوبيورين، ويتقاطع معه في الإنزيمات التي تفكّكه وفي القابلية الوراثية لأذاه، لكن له خطراً خاصّاً به على أوعية الكبد الدقيقة. يُصرف ضمن خطّة علاج يضعها طبيب أمراض الدم، ويحتاج متابعة بتحاليل الدم والكبد، ولا يصحّ استعماله خارج هذه الخطّة أو إطالته من تلقاء النفس.',
    en: 'Tioguanine, also written thioguanine, is a chemotherapy taken by mouth as tablets, from the purine analogues, a class that resembles the building blocks of DNA. It works much like mercaptopurine and overlaps with it in the enzymes that break it down and in the inherited susceptibility to its harm, but it has a specific danger of its own to the small blood vessels of the liver. It is dispensed within a treatment plan set by a haematologist and needs monitoring with blood and liver tests, and it should not be used outside that plan or prolonged on your own initiative.'
  },
  why: {
    ar: 'يُستعمل في علاج ابيضاض الدم النقوي الحادّ، وهو سرطان يبدأ في الخلايا التي تصنع كريات الدم البيضاء، ويُعطى عادةً ضمن مجموعة من الأدوية الكيميائية لإحداث الهدأة ثم تثبيتها. وتنصّ النشرة الأمريكية على أنه لا يُنصح به علاجاً للمداومة أو علاجاً مستمرّاً طويل الأمد، لأن خطر أذاه للكبد مرتفع في هذا الاستعمال، وقد ظهر ذلك في نسبة عالية من الأطفال الذين أخذوه في مرحلة المداومة لابيضاض الدم اللمفاوي الحادّ. ولهذا فاختياره وتحديد مدّته قرار المختصّ وحده.',
    en: 'It is used to treat acute myeloid leukaemia, a cancer that starts in the cells that make white blood cells, and is usually given as part of a group of chemotherapy drugs to bring about remission and then consolidate it. The American label states that it is not recommended for maintenance therapy or long-term continuous treatment, because the risk of liver damage is high in that use, as seen in a high proportion of children who took it in the maintenance phase of acute lymphoblastic leukaemia. So choosing it and deciding how long to use it is the decision of the specialist alone.'
  },
  how: {
    ar: 'يتحوّل التيوجوانين داخل الخلية إلى نيوكليوتيدات فعّالة تشبه موادّ بناء الحمض النووي، فتندسّ في مكانها وتعطّل صنعه، فيبطؤ نموّ الخلايا السرطانية أو يتوقّف. ولأنه يضرب الخلايا السريعة الانقسام، يصيب معها نخاع العظم فيهبط تعداد الدم. ويشترك مع الميركابتوبيورين في الإنزيم الذي يفكّكه، فمن ورث ضعفاً فيه يتراكم الدواء الفعّال في خلاياه ويشتدّ هبوط الدم. أما أذى الكبد فيأتي من إتلاف البطانة الداخلية لأوعيته الدقيقة، فتنسدّ الأوردة الصغيرة داخل الكبد.',
    en: 'Inside the cell tioguanine is converted into active nucleotides that resemble the building blocks of DNA, so they slip into their place and disrupt its production, slowing or stopping the growth of cancer cells. Because it hits rapidly dividing cells, it also affects the bone marrow, so the blood count falls. It shares with mercaptopurine the enzyme that breaks it down, so anyone who inherited a weakness in it builds up the active drug in their cells and the fall in blood counts is more severe. The liver damage comes from injury to the inner lining of its small vessels, so the small veins inside the liver become blocked.'
  },
  effects: {
    ar: 'من آثاره الشائعة التي تزول غالباً وحدها: غثيان وقيء، وفقدان شهية وتغيّر في الوزن، وتقرّحات في الفم، وصداع. وأهمّ أثر غير ظاهر هو هبوط كريات الدم، فتضعف المناعة ويسهل النزف ويظهر التعب والشحوب، ولهذا تُجرى تحاليل الدم بانتظام وقد يعدّل الطبيب الخطّة بحسبها. وتُتابع وظائف الكبد كذلك، لأن التغيّر فيها قد يسبق الأعراض. وأي أثر يستمرّ أو يشتدّ يُذكر للفريق في الموعد التالي على الأقل، أما ما في حقل التحذير فلا ينتظر الموعد.',
    en: 'Its common effects, which usually pass on their own, include nausea and vomiting, loss of appetite and weight change, mouth sores and headache. The most important hidden effect is a fall in blood cells, so immunity weakens, bleeding comes easily and tiredness and pallor appear, which is why blood tests are done regularly and the doctor may adjust the plan accordingly. Liver function is also monitored, because changes may come before symptoms. Any effect that persists or worsens should be mentioned to the team at the next appointment at the latest, while what is in the warning field does not wait for an appointment.'
  },
  warning: {
    ar: 'اذهب إلى الطوارئ أو اتصل بالفريق فوراً عند علامات انسداد أوردة الكبد التي تصفها النشرة: اصفرار الجلد أو العينين، أو كبد متضخّم مؤلم تحت الأضلاع اليمنى، أو زيادة سريعة في الوزن من احتباس السوائل، أو انتفاخ البطن بالسوائل. واتصل فوراً كذلك عند: حمّى أو التهاب حلق أو سعال أو أي علامة عدوى، أو نزف أو تكدّم غير معتاد، أو قيء فيه دم أو براز أسود قطراني، أو تورّم في الوجه أو الذراعين أو الساقين، أو ضيق نفس أو دوخة، أو تعب وضعف غير معتادين.',
    en: 'Go to the emergency department or call the team at once with the signs of blocked liver veins that the label describes: yellow skin or eyes, a tender enlarged liver under the right ribs, rapid weight gain from fluid retention, or a belly swollen with fluid. Also call at once for: fever, sore throat, cough or any sign of infection; unusual bleeding or bruising; vomiting blood or black tarry stools; swelling of the face, arms or legs; breathlessness or dizziness; or unusual tiredness and weakness.'
  },
  interact: {
    ar: 'أخبر الطبيب والصيدلي بكل ما تتناوله من أدوية وفيتامينات وأعشاب، فقد يحتاج الطبيب إلى تعديل الخطّة أو مراقبتك عن قرب لآثار جانبية أشدّ. وأخبره إن كنت أخذت التيوجوانين أو الميركابتوبيورين سابقاً ولم ينفع، لأن الدواءين متقاربان فقد لا ينفع أحدهما حيث فشل الآخر. ويحتاج الطبيب أن يعرف إن كانت عندك حالة وراثية تزيد خطر آثاره الشديدة. ولا تأخذ أي لقاح دون موافقة الطبيب، فالمناعة منخفضة واللقاحات الحيّة قد تكون خطرة. ولا تبدأ دواءً جديداً دون سؤال الفريق ما دمت تأخذه.',
    en: 'Tell the doctor and pharmacist about all the medicines, vitamins and herbs you take, as the doctor may need to adjust the plan or watch you closely for more severe side effects. Tell them if you have taken tioguanine or mercaptopurine before without success, because the two drugs are closely related, so one may not work where the other failed. The doctor also needs to know if you have an inherited condition that raises the risk of its severe effects. Do not have any vaccine without the doctor agreeing, as immunity is low and live vaccines can be dangerous. Do not start any new medicine without asking the team while you are taking it.'
  },
  avoid: {
    ar: 'لا تحملي ولا ترضعي أثناء أخذه، فهو قد يؤذي الجنين والرضيع، واستعملي وسيلة منع حمل فعّالة يتّفق عليها الفريق. ومن عنده مرض في الكبد عليه أن يخبر الطبيب قبل البدء، لأن الكبد هو موضع خطره الخاصّ. ومن عنده حالة وراثية معروفة تُضعف تفكيك أدوية البيورين يحتاج تقديراً خاصّاً، فقد يرفع ذلك خطر الآثار الشديدة. ولا يُستعمل علاجاً مستمرّاً طويل الأمد بنصّ النشرة الأمريكية، وخصوصاً عند الأطفال، بسبب ارتفاع خطر أذى الكبد في هذا الاستعمال.',
    en: 'Do not become pregnant or breastfeed while taking it, as it may harm an unborn or breastfed baby, and use an effective method of contraception agreed with the team. Anyone with liver disease must tell the doctor before starting, because the liver is its particular point of danger. Anyone with a known inherited condition that weakens the breakdown of purine drugs needs special assessment, as this may raise the risk of severe effects. By the American label it is not used as long-term continuous treatment, especially in children, because of the high risk of liver damage in that use.'
  },
  updated: '2026-09-11',
  src: [
    'https://medlineplus.gov/druginfo/meds/a682099.html',
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=44b0c461-47fb-4106-ba11-6ed85530235c'
  ]
};

RX_BODY['hydroxyurea'] = {
  what: {
    ar: 'الهيدروكسي يوريا، ويُسمّى في بريطانيا الهيدروكسي كارباميد، دواء من فصيلة مضادّات الأيض يؤخذ بالفم كبسولات أو أقراصاً. يختلف عن أغلب أدوية هذه البطاقات بأنه لا يقتصر على السرطان: فهو علاج أساسي في فقر الدم المنجلي أيضاً، ويأخذه المريض في بيته لفترات طويلة. ولأنه دواء كيميائي، تنصح النشرة بلبس قفّازين عند التعامل مع الكبسولات أو الأقراص وغسل اليدين قبل اللمس وبعده.',
    en: 'Hydroxyurea, called hydroxycarbamide in Britain, is an antimetabolite taken by mouth as capsules or tablets. It differs from most drugs in these cards in that it is not limited to cancer: it is also a key treatment for sickle cell anaemia, and the patient takes it at home for long periods. Because it is a chemotherapy drug, the leaflet advises wearing gloves when handling the capsules or tablets and washing hands before and after touching them.'
  },
  why: {
    ar: 'له استعمالان كبيران. الأول فقر الدم المنجلي عند الكبار والأطفال، حيث يقلّل عدد نوبات الألم والحاجة إلى نقل الدم. والثاني أمراض الدم والسرطان: ابيضاض الدم النقوي المزمن، وسرطانات الرأس والعنق كالفم واللسان والحلق واللوزتين والجيوب مع العلاج الإشعاعي، وأمراض النقي المزمنة التي تذكرها النشرة البريطانية وهي كثرة الحمر الحقيقية وكثرة الصفائح الأساسية والتليّف النقوي. وفي كل ذلك يقرّر الطبيب الخطّة ويعدّلها بحسب تحاليل الدم الدورية.',
    en: 'It has two major uses. The first is sickle cell anaemia in adults and children, where it reduces the number of painful crises and the need for blood transfusions. The second is blood disorders and cancer: chronic myeloid leukaemia, head and neck cancers such as those of the mouth, tongue, throat, tonsils and sinuses together with radiotherapy, and the chronic bone marrow disorders mentioned in the British leaflet, namely polycythaemia vera, essential thrombocythaemia and myelofibrosis. In all of these the doctor decides the plan and adjusts it according to regular blood tests.'
  },
  how: {
    ar: 'يمنع الدواء الخلايا من صنع حمضها النووي وإصلاحه، فيبطئ تكاثر الخلايا السريعة الانقسام أو يوقفه. وهذا ينفع في السرطان وفي أمراض النقي التي يصنع فيها الجسم كريات أو صفائح أكثر من حاجته، إذ يكبح هذا الإفراط. أما في فقر الدم المنجلي فتقول النشرة إنه يمنع تكوّن كريات الدم الحمراء المنجلية الشكل، وهي الكريات المتصلّبة التي تسدّ الأوعية الصغيرة فتسبّب نوبات الألم. ولأنه يكبح نخاع العظم، فالتحاليل الدورية هي صمّام أمانه.',
    en: 'The drug stops cells from making and repairing their DNA, slowing or stopping the multiplication of rapidly dividing cells. This helps in cancer and in bone marrow disorders where the body makes more cells or platelets than it needs, by holding back that excess. In sickle cell anaemia, the leaflet says it prevents the formation of sickle-shaped red blood cells, the stiff cells that block small vessels and cause painful crises. Because it holds back the bone marrow, regular blood tests are its safety valve.'
  },
  effects: {
    ar: 'من آثاره الشائعة: غثيان وقيء، وإسهال أو إمساك، وفقدان شهية أو زيادة وزن، وتقرّحات في الفم والحلق، ودوخة وصداع، وتساقط الشعر، وتغيّرات في الجلد والأظافر كالطفح والشحوب واسمرار الأظافر. وأهمّ أثر هو هبوط كريات الدم، فيسهل التكدّم ونزف اللثة والأنف، وتكثر العدوى، ويظهر ضيق النفس والشحوب. وتذكر النشرة أنه يرفع خطر سرطانات أخرى منها سرطان الجلد، ولهذا يُتجنّب التعرّض الطويل للشمس مع ملابس ساترة ونظّارة وواقٍ شمسي. وقد يُخلّ بقراءة بعض أجهزة قياس السكّر المستمرّ.',
    en: 'Its common effects include nausea and vomiting, diarrhoea or constipation, loss of appetite or weight gain, sores in the mouth and throat, dizziness and headache, hair loss, and skin and nail changes such as rash, pallor and darkened nails. The most important effect is a fall in blood cells, so bruising and bleeding from the gums and nose come easily, infections become more frequent, and breathlessness and pallor appear. The leaflet notes that it raises the risk of other cancers, including skin cancer, so long sun exposure is avoided with covering clothes, sunglasses and sunscreen. It may disturb the readings of some continuous glucose monitors.'
  },
  warning: {
    ar: 'اتصل بالطبيب فوراً عند: حمّى أو قشعريرة أو التهاب حلق أو سعال مستمرّ أو تعب شديد أو أي علامة عدوى؛ أو نزف أو تكدّم غير معتاد، أو براز أسود قطراني أو فيه دم، أو قيء دم؛ أو ألم شديد مفاجئ في البطن أو الظهر، وقد يكون التهاباً في البنكرياس يوقف الدواء نهائياً؛ أو قرحة أو جرح جديد في الساق، فالنشرة توقفه عند ظهور تقرّحات الأوعية الجلدية؛ أو ألم وتورّم وفقاعات في الجلد؛ أو دم في البول؛ أو اصفرار العينين؛ أو خدر أو حرقة في اليدين والقدمين؛ أو خفقان سريع؛ أو ضيق نفس وسعال جديد.',
    en: 'Call the doctor at once for: fever, chills, a sore throat, a persistent cough, severe tiredness or any sign of infection; unusual bleeding or bruising, black tarry or bloody stools, or vomiting blood; sudden severe pain in the abdomen or back, which may be pancreatitis and stops the drug for good; a new ulcer or wound on the leg, as the label stops it when skin vessel ulcers appear; pain, swelling and blisters on the skin; blood in the urine; yellow eyes; numbness or burning in the hands and feet; a fast heartbeat; or breathlessness with a new cough.'
  },
  interact: {
    ar: 'أخطر ما تنصّ عليه النشرة الأمريكية يخصّ مرضى فيروس نقص المناعة: جمعه مع الديدانوسين، مع الستافودين أو بدونه، أدّى إلى التهاب بنكرياس قاتل وغير قاتل وإلى فشل كبد مميت، فمن يتعالج من هذا الفيروس يخبر طبيبه قبل البدء. واللقاحات لا تؤخذ دون موافقة الطبيب، والحيّة منها ممنوعة أثناء العلاج ولفترة بعده، أما غير الحيّة كلقاح الإنفلونزا فتجيزها النشرة البريطانية عادةً. وأخبر الفريق بكل دواء ومكمّل وعشبة، وتذكر النشرة البريطانية عصير الجريب فروت ممّا قد يتعارض.',
    en: 'The most serious point in the American label concerns patients with HIV: combining it with didanosine, with or without stavudine, led to fatal and non-fatal pancreatitis and to deadly liver failure, so anyone being treated for this virus must tell their doctor before starting. Vaccines are not given without the doctor agreeing, and live ones are not allowed during treatment and for a period afterwards, while non-live ones such as the flu vaccine are usually allowed according to the British leaflet. Tell the team about every medicine, supplement and herb, and the British leaflet lists grapefruit juice among possible interactions.'
  },
  avoid: {
    ar: 'لا تحملي أثناء أخذه، ويُجرى اختبار حمل قبل البدء، وتستعمل المرأة وسيلة منع حمل فعّالة أثناء العلاج ولستّة أشهر على الأقل بعده. وعلى الرجل وشريكته منع الحمل أثناء العلاج ولفترة بعده تتراوح بين ستّة أشهر وسنة بحسب المستحضر. ولا ترضعي أثناء أخذه. وقد يُنقص خصوبة الرجل، فيُناقش ذلك مع الطبيب قبل البدء. ويخبر الطبيب من عنده مرض في الكلى أو الكبد أو يخضع للغسيل الكلوي، أو عنده قرح في الساقين، أو ارتفاع حمض اليوريك، أو تلقّى علاجاً إشعاعياً أو كيميائياً سابقاً.',
    en: 'Do not become pregnant while taking it; a pregnancy test is done before starting, and a woman uses effective contraception during treatment and for at least six months afterwards. A man and his partner must prevent pregnancy during treatment and for a period afterwards ranging from six months to a year depending on the product. Do not breastfeed while taking it. It may reduce male fertility, so this is discussed with the doctor before starting. Anyone with kidney or liver disease or on dialysis, with leg ulcers, with high uric acid, or who has had previous radiotherapy or chemotherapy must tell the doctor.'
  },
  updated: '2026-09-11',
  src: [
    'https://medlineplus.gov/druginfo/meds/a682004.html',
    'https://www.cancerresearchuk.org/about-cancer/treatment/drugs/hydroxycarbamide',
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6053c775-68de-45e4-9af9-33b18fd0e140'
  ]
};

RX_BODY['calcium-folinate'] = {
  what: {
    ar: 'فولينات الكالسيوم، وتُعرف بالليكوفورين وبحمض الفولينيك، صورة جاهزة فعّالة من عائلة حمض الفوليك، تصنّفها النشرة بين نظائر حمض الفوليك. وهي ليست دواءً كيميائياً بذاتها، لكنها ترافق العلاج الكيميائي في المستشفى: تُعطى حقناً في الوريد أو العضل. وخطأها الأشهر في الذهن أن اسمها يشبه حمض الفوليك الذي يُباع في الصيدليات، فيُظنّ أنهما شيء واحد يُبدَّل أحدهما بالآخر، وهذا غير صحيح: لها دواعٍ محدّدة ومواعيد دقيقة يضعها الفريق.',
    en: 'Calcium folinate, known as leucovorin and folinic acid, is a ready-active form from the folic acid family, which the leaflet classes among the folic acid analogues. It is not a chemotherapy drug in itself, but it accompanies chemotherapy in hospital: it is given as an injection into a vein or a muscle. The best-known mistake about it is that its name resembles the folic acid sold in pharmacies, so people assume they are the same thing and can be swapped, which is not true: it has specific indications and precise timings set by the team.'
  },
  why: {
    ar: 'تذكر النشرة أربعة دواعٍ. الأول حماية الخلايا السليمة من أذى الميثوتريكسيت حين يُعطى بمقادير عالية لعلاج السرطان، ومنه ساركوما العظم، وهو ما يُسمّى الإنقاذ. والثاني علاج من أخذ مقداراً زائداً من الميثوتريكسيت أو من دواء مشابه يعاكس حمض الفوليك. والثالث فقر الدم الضخم الأرومات الناتج عن نقص حمض الفوليك حين لا يمكن العلاج بالفم. والرابع مرافقة الفلورويوراسيل في علاج سرطان القولون والمستقيم المتقدّم لتقوية أثره.',
    en: 'The leaflet lists four indications. The first is protecting healthy cells from the harm of methotrexate when it is given in high amounts to treat cancer, including bone sarcoma, which is called rescue. The second is treating someone who has taken too much methotrexate or a similar drug that opposes folic acid. The third is megaloblastic anaemia caused by folic acid deficiency when treatment by mouth is not possible. The fourth is accompanying fluorouracil in the treatment of advanced colorectal cancer to strengthen its effect.'
  },
  how: {
    ar: 'تحتاج كل خلية تنقسم إلى الفولات النشطة لتصنع حمضها النووي. والميثوتريكسيت من مضادّات حمض الفوليك: يحرم الخلايا منها فتموت الخلايا السريعة الانقسام، السرطانية منها والسليمة. وفولينات الكالسيوم تعطي الخلايا الفولات جاهزة بصورة لا يعيقها الميثوتريكسيت، فتنقذ الخلايا السليمة كنخاع العظم وبطانة الفم والأمعاء من أذاه. ولهذا فتوقيتها بعد الميثوتريكسيت محسوب بدقّة. أما مع الفلورويوراسيل فعملها معاكس في النتيجة: تزيد قبضته على الخلايا فيقوى أثره، وتقوى معه آثاره الجانبية.',
    en: 'Every dividing cell needs active folate to make its DNA. Methotrexate is a folic acid antagonist: it deprives cells of it, so rapidly dividing cells die, cancerous and healthy alike. Calcium folinate gives cells ready-made folate in a form that methotrexate cannot block, rescuing healthy cells such as the bone marrow and the lining of the mouth and gut from its harm. That is why its timing after methotrexate is precisely calculated. With fluorouracil its effect is the opposite in outcome: it tightens that drug grip on cells so its effect grows stronger, and so do its side effects.'
  },
  effects: {
    ar: 'فولينات الكالسيوم وحدها قليلة الآثار عند أغلب الناس، ولا تذكر النشرة أثراً شائعاً محدّداً، وتطلب الاتصال بالطبيب عند أي مشكلة غير معتادة. وقد تحدث تفاعلات تحسّسية كالطفح والشرى والحكّة. ونادراً ما سُجّلت نوبات تشنّج أو إغماء، وغالباً مع أدوية الفلورويوراسيل ولم تُثبت علاقتها السببية. أما حين تُعطى مع الفلورويوراسيل فالآثار المعتادة للجمع تكون أقوى: تقرّحات الفم والإسهال تحديداً، وخصوصاً عند كبار السن والمنهكين، وهذه من أثر الجمع لا من الفولينات وحدها.',
    en: 'Calcium folinate on its own causes few effects in most people, the leaflet names no specific common effect, and it asks you to call the doctor about any unusual problem. Allergic reactions such as rash, hives and itching may occur. Seizures or fainting have rarely been recorded, usually with fluorouracil-type drugs, and a causal link has not been established. When it is given with fluorouracil, the usual effects of the combination are stronger: mouth sores and diarrhoea in particular, especially in older and frail people, and these come from the combination rather than from the folinate alone.'
  },
  warning: {
    ar: 'اذهب إلى الطوارئ عند: صعوبة في التنفّس أو البلع، أو تورّم في الوجه أو الحلق، أو طفح منتشر مع حكّة، أو نوبة تشنّج، أو إغماء. وإن كانت تُعطى مع الفلورويوراسيل فاتصل بالفريق فوراً عند إسهال شديد أو مستمرّ، أو تقرّحات فم تمنعك من الأكل والشرب، فالنشرة تحذّر من أن الجمع قد يصير شديد السمّية بسرعة خاصّة عند كبار السن. وإن كانت إنقاذاً من الميثوتريكسيت فهي تُعطى بمواعيد متتالية حتى تُثبت التحاليل خروجه من الجسم، فلا تُوقف ولا تُؤخّر قبل أن يقول الفريق، وأخبرهم فوراً إن قلّ بولك.',
    en: 'Go to the emergency department for: difficulty breathing or swallowing, swelling of the face or throat, a spreading itchy rash, a seizure or fainting. If it is given with fluorouracil, call the team at once for severe or persistent diarrhoea, or mouth sores that stop you eating and drinking, as the label warns the combination can quickly become severely toxic, especially in older people. If it is rescue after methotrexate, it is given at successive times until tests prove the methotrexate has left the body, so it must not be stopped or delayed before the team says so, and tell them at once if you pass less urine.'
  },
  interact: {
    ar: 'تقوّي فولينات الكالسيوم سمّية الفلورويوراسيل، ولهذا يُعطى الفلورويوراسيل بمقدار أقلّ من المعتاد حين يُجمعان، ولا يُخلطان في كيس تنقيط واحد لأنهما قد يترسّبان. وقد تتعارض مع أدوية الصرع كالفينوباربيتال والفينيتوين والبريميدون فيضعف ضبط النوبات، فمن يأخذ أحدها يخبر الطبيب. وقد تُضعف أثر الترايميثوبريم مع السلفاميثوكسازول، وهو مضادّ حيوي شائع. والمقادير العالية منها قد تُضعف أثر الميثوتريكسيت الذي يُعطى داخل القناة الشوكية. وأخبر الفريق بكل دواء ومكمّل تتناوله.',
    en: 'Calcium folinate increases the toxicity of fluorouracil, which is why fluorouracil is given at a lower amount than usual when the two are combined, and they are not mixed in one drip bag because they may form a precipitate. It may interact with epilepsy medicines such as phenobarbital, phenytoin and primidone, weakening seizure control, so anyone taking one of them must tell the doctor. It may weaken the effect of trimethoprim with sulfamethoxazole, a common antibiotic. High amounts of it may weaken methotrexate given into the spinal canal. Tell the team about every medicine and supplement you take.'
  },
  avoid: {
    ar: 'لا تُستعمل لعلاج فقر الدم الخبيث ولا أي فقر دم ضخم الأرومات سببه نقص فيتامين ب١٢، فهي تُحسّن صورة الدم في التحاليل بينما يستمرّ تلف الأعصاب في التقدّم خفيةً. ولا تُعطى داخل القناة الشوكية أبداً، فالنشرة تنصّ بحروف كبيرة على أنها قد تكون ضارّة أو قاتلة بهذا الطريق. ويخبر الطبيب من عنده مرض في الكلى، أو سوائل متجمّعة في الصدر أو البطن لأنها تؤخّر خروج الميثوتريكسيت، أو ورم في الدماغ أو الجهاز العصبي. والحامل والمرضع تناقشان استعمالها مع الطبيب.',
    en: 'It is not used to treat pernicious anaemia or any megaloblastic anaemia caused by vitamin B12 deficiency, because it improves the blood picture in tests while nerve damage continues to progress unseen. It is never given into the spinal canal, as the label states in capital letters that it may be harmful or fatal by that route. Anyone with kidney disease, fluid collected in the chest or abdomen because it delays the clearance of methotrexate, or a tumour of the brain or nervous system must tell the doctor. A pregnant or breastfeeding woman discusses its use with the doctor.'
  },
  updated: '2026-09-11',
  src: [
    'https://medlineplus.gov/druginfo/meds/a608038.html',
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4b72d1fd-f389-45d9-b43b-510b45c92263'
  ]
};

RX_BODY['doxorubicin'] = {
  what: {
    ar: 'الدوكسوروبيسين، ويُعرف بالأدرياميسين، دواء كيميائي من فصيلة الأنثراسيكلينات، وهو سائل أحمر اللون يُعطى في الوريد داخل مركز الأورام عبر قنية أو خطّ مركزي، وقد يُعطى داخل المثانة مباشرة لعلاج سرطان بطانتها. ويدخل في خطط كثيرة مع أدوية أخرى. ولأنه قد يُتلف عضلة القلب، يُفحص القلب بتخطيط وصورة بالموجات الصوتية قبل البدء وأثناء العلاج وبعده. ولونه الأحمر هو سبب احمرار البول بعده ليوم أو يومين، وهذا لا يضرّ.',
    en: 'Doxorubicin, also known as Adriamycin, is a chemotherapy drug from the anthracycline class, a red liquid given into a vein in a cancer centre through a cannula or central line, and it may be given directly into the bladder to treat cancer of its lining. It is part of many plans with other drugs. Because it can damage the heart muscle, the heart is checked with an ECG and an ultrasound scan before starting, during treatment and afterwards. Its red colour is why the urine turns red for a day or two after it, which is harmless.'
  },
  why: {
    ar: 'يُستعمل في طيف واسع من السرطانات: سرطان الثدي، والمثانة، والرئة، والمعدة، والمبيض، والغدة الدرقية، واللمفوما بنوعيها هودجكن وغير هودجكن، وابيضاض الدم اللمفاوي الحادّ والنقوي الحادّ، وساركوما الأنسجة الرخوة والعظام، وأورام الأطفال كورم الأرومة العصبية وورم ويلمز. وتذكر مدلاين بلس استعمالات أخرى منها سرطانات الرحم وعنق الرحم والبروستاتا والبنكرياس والكبد، والورم النقوي المتعدّد، وساركوما كابوسي. واختياره ضمن أي خطّة قرار فريق الأورام.',
    en: 'It is used in a wide range of cancers: breast, bladder, lung, stomach, ovarian and thyroid cancer, both Hodgkin and non-Hodgkin lymphoma, acute lymphoblastic and acute myeloid leukaemia, soft tissue and bone sarcomas, and childhood tumours such as neuroblastoma and Wilms tumour. MedlinePlus mentions other uses including cancers of the uterus, cervix, prostate, pancreas and liver, multiple myeloma and Kaposi sarcoma. Choosing it within any plan is the decision of the oncology team.'
  },
  how: {
    ar: 'تحتاج الخلية السرطانية حين تنقسم إلى أن تفكّ التفاف حمضها النووي ثم تعيد ربطه، وتستعين في ذلك بإنزيم يُسمّى توبو إيزوميراز الثاني. يسدّ الدوكسوروبيسين هذا الإنزيم، فتتكسّر سلاسل الحمض النووي وتعجز الخلية عن الانقسام فتموت. ولأنه يضرب الخلايا السريعة الانقسام، يصيب معها نخاع العظم وبطانة الفم والأمعاء وبصيلات الشعر. أما عضلة القلب فتتأثّر بطريقة خاصّة بهذه الفصيلة، ولهذا يُفحص القلب قبل العلاج وأثناءه وبعده، ويسأل الطبيب عن أي علاج إشعاعي سابق على الصدر.',
    en: 'When a cancer cell divides it needs to untwist its DNA and then rejoin it, and it uses an enzyme called topoisomerase two for this. Doxorubicin blocks this enzyme, so the DNA strands break and the cell cannot divide and dies. Because it hits rapidly dividing cells, it also affects the bone marrow, the lining of the mouth and gut, and the hair follicles. The heart muscle is affected in a way specific to this class, which is why the heart is checked before, during and after treatment, and the doctor asks about any previous radiotherapy to the chest.'
  },
  effects: {
    ar: 'من آثاره الشائعة: غثيان وقيء، وتقرّحات في الفم والحلق، وفقدان شهية مع نقص أو زيادة في الوزن، وألم في البطن وإسهال، وتساقط الشعر، وتعب وضعف غير معتادين، واحمرار البول ليوم أو يومين، واسمرار الأظافر أو انفصالها عن فراشها، وتهيّج العينين، ووخز أو حرقة في اليدين والقدمين. وأهمّ أثر غير ظاهر هبوط كريات الدم، فتضعف المناعة ويسهل النزف ويظهر فقر الدم، ولهذا تُجرى تحاليل الدم قبل الجلسات. وتغيّرات عضلة القلب أو نظمه شائعة معه، وتُكتشف بالفحوص قبل أن يُحسّ بها.',
    en: 'Its common effects include nausea and vomiting, mouth and throat sores, loss of appetite with weight loss or gain, stomach pain and diarrhoea, hair loss, unusual tiredness and weakness, red urine for a day or two, darkening of the nails or their separation from the nail bed, eye irritation, and tingling or burning in the hands and feet. The most important hidden effect is a fall in blood cells, so immunity weakens, bleeding comes easily and anaemia appears, which is why blood tests are done before sessions. Changes in the heart muscle or rhythm are common with it and are picked up by tests before they are felt.'
  },
  warning: {
    ar: 'اتصل بالفريق فوراً، ولو ليلاً، عند حرارة سبعة وثلاثين ونصف درجة أو أكثر أو أي علامة عدوى. واذهب إلى الطوارئ عند: ضيق نفس أو ألم في الصدر، أو تورّم اليدين أو القدمين أو الساقين، أو خفقان سريع أو غير منتظم، وهذه علامات أذى القلب، وقد تظهر أثناء العلاج أو بعده بأشهر أو سنوات، فلا تتجاهلها لأن العلاج انتهى؛ أو صعوبة في التنفّس أو البلع مع شرى وحكّة؛ أو نوبة تشنّج؛ أو نزف أو تكدّم غير معتاد أو براز أو قيء فيه دم. وأثناء التنقيط أخبر الممرّض فوراً عند ألم أو حرقة أو تورّم في موضعه، فتسرّبه تحت الجلد يُتلف الأنسجة.',
    en: 'Call the team at once, even at night, with a temperature of thirty-seven and a half degrees or more or any sign of infection. Go to the emergency department for: breathlessness or chest pain, swelling of the hands, feet or legs, or a fast or irregular heartbeat, which are signs of heart damage and may appear during treatment or months or years after it, so do not ignore them because treatment has ended; difficulty breathing or swallowing with hives and itching; a seizure; or unusual bleeding or bruising, or blood in the stool or vomit. During the drip, tell the nurse at once about pain, burning or swelling at the site, because leakage under the skin damages the tissue.'
  },
  interact: {
    ar: 'تذكر مدلاين بلس أدوية يجب إخبار الطبيب بها: السيكلوفوسفاميد، وأدوية الفصيلة نفسها كالدونوروبيسين والإبيروبيسين والإيداروبيسين والميتوكسانترون، والباكليتاكسيل، والتراستوزوماب، والفيراباميل، والآزاثيوبرين، والسيكلوسبورين، والميثوتريكسيت، والبروجستيرون. وأخبره إن تلقّيت علاجاً إشعاعياً على الصدر سابقاً. ولا لقاحات دون موافقة الطبيب، والحيّة منها ممنوعة أثناء العلاج وحتى سنة بعده. وأخبر الفريق بالفيتامينات والأعشاب والأدوية التي بلا وصفة.',
    en: 'MedlinePlus lists medicines you must tell the doctor about: cyclophosphamide, drugs of the same class such as daunorubicin, epirubicin, idarubicin and mitoxantrone, paclitaxel, trastuzumab, verapamil, azathioprine, ciclosporin, methotrexate and progesterone. Tell the doctor if you have had radiotherapy to the chest before. No vaccines without the doctor agreeing, and live ones are not allowed during treatment and for up to a year afterwards. Tell the team about vitamins, herbs and non-prescription medicines.'
  },
  avoid: {
    ar: 'لا يُعطى لمن أصابته حساسية منه أو من أدوية فصيلته. ويُخبَر الطبيب بأي مرض قلب أو جلطة قلبية سابقة أو علاج إشعاعي على الصدر، وبأي مرض في الكبد لأنه قد يستلزم تعديلاً. وهو قد يؤذي الجنين، فيُتجنّب الحمل أثناء العلاج ولسبعة أشهر على الأقل بعده بحسب النشرة البريطانية، ولا رضاعة أثناء العلاج. وقد يغيّر الدورة الشهرية ويُنقص إنتاج الحيوانات المنوية. وتذكر النشرة أنه يرفع خطر الإصابة لاحقاً بابيضاض الدم، خاصّة مع المقادير العالية أو مع أدوية كيميائية معيّنة.',
    en: 'It is not given to anyone allergic to it or to drugs of its class. The doctor must be told about any heart disease, previous heart attack or radiotherapy to the chest, and about any liver disease, as this may need an adjustment. It may harm an unborn baby, so pregnancy is avoided during treatment and for at least seven months afterwards according to the British leaflet, and there is no breastfeeding during treatment. It may change the menstrual cycle and reduce sperm production. The leaflet notes that it raises the risk of later developing leukaemia, especially with high amounts or with certain other chemotherapy drugs.'
  },
  updated: '2026-09-11',
  src: [
    'https://medlineplus.gov/druginfo/meds/a682221.html',
    'https://www.cancerresearchuk.org/about-cancer/treatment/drugs/doxorubicin'
  ]
};

RX_BODY['doxorubicin-liposomal'] = {
  what: {
    ar: 'هذا هو الدوكسوروبيسين نفسه، لكنه محفوظ داخل كريّات دهنية دقيقة جداً تُسمّى الجسيمات الشحمية، مغطّاة بطبقة تجعلها تبقى في مجرى الدم مدّة أطول من الدواء العادي. يُعطى بالتنقيط في الوريد داخل مركز الأورام. ولأن تغليفه يغيّر طريقة توزّعه في الجسم، تختلف آثاره الجانبية البارزة عن الدوكسوروبيسين العادي، وله نشرته المستقلة واسمه المستقلّ، فلا يُعامَل كأنه النسخة نفسها ولا يُخلط بينهما في الوصفة أو الصيدلية.',
    en: 'This is doxorubicin itself, but held inside extremely tiny fatty spheres called liposomes, coated with a layer that makes them stay in the bloodstream longer than the ordinary drug. It is given by drip into a vein in a cancer centre. Because the coating changes the way it spreads through the body, its prominent side effects differ from ordinary doxorubicin, and it has its own leaflet and its own name, so it is not treated as the same product and the two must not be confused in a prescription or a pharmacy.'
  },
  why: {
    ar: 'تذكر مدلاين بلس ثلاثة استعمالات: سرطان المبيض الذي لم يستجب لعلاج سابق أو ساء بعده؛ وساركوما كابوسي المرتبطة بالإيدز، وهي ورم يسبّب نموّاً غير طبيعي للأنسجة تحت الجلد وفي مواضع أخرى، حين لم تنفع أدوية سابقة؛ والورم النقوي المتعدّد، وهو سرطان في نخاع العظم، مع دواء كيميائي آخر حين فشلت علاجات سابقة. وتذكر النشرة البريطانية أنه يُستعمل في عدّة أنواع من السرطان. وكما في كل أدوية الأورام، فالخطّة يضعها الفريق بحسب المرض ومرحلته وحالة المريض.',
    en: 'MedlinePlus lists three uses: ovarian cancer that did not respond to earlier treatment or worsened after it; AIDS-related Kaposi sarcoma, a tumour causing abnormal tissue growth under the skin and elsewhere, when earlier medicines did not work; and multiple myeloma, a cancer of the bone marrow, together with another chemotherapy drug when earlier treatments failed. The British leaflet says it is used for several types of cancer. As with all cancer drugs, the plan is set by the team according to the disease, its stage and the condition of the patient.'
  },
  how: {
    ar: 'المادّة الفعّالة هي الدوكسوروبيسين، وهو يسدّ إنزيم توبو إيزوميراز الثاني الذي تحتاجه الخلية السرطانية لتفكّ حمضها النووي وتعيد ربطه أثناء الانقسام، فتعجز عن الانقسام وتموت. والجديد هو الغلاف: فالكريّات الشحمية المغطّاة تُبقي الدواء في مجرى الدم مدّة أطول بحسب النشرة البريطانية، فيتغيّر توزّعه في الأنسجة. ولهذا صار أشهر آثاره ما يصيب جلد الكفّين والقدمين، بينما يبقى يحمل تحذير القلب الذي تحمله فصيلته كلها.',
    en: 'The active substance is doxorubicin, which blocks the enzyme topoisomerase two that a cancer cell needs to untwist and rejoin its DNA during division, so it cannot divide and dies. What is new is the coating: according to the British leaflet, the coated liposomes keep the drug in the bloodstream longer, so its distribution in the tissues changes. That is why its best-known effect is on the skin of the palms and soles, while it still carries the heart warning that its whole class carries.'
  },
  effects: {
    ar: 'أشهر آثاره متلازمة اليد والقدم: وخز وحرقة واحمرار وتورّم وتقشّر وأحياناً فقاعات أو قروح في راحتي اليدين وباطن القدمين. ومن آثاره الشائعة أيضاً: غثيان وقيء، وفقدان شهية، وإسهال أو إمساك، وتعب ودوخة، وتساقط الشعر، وتقرّحات الفم، وبول برتقالي محمرّ بعد الجلسة لا يضرّ. ويُهبط كريات الدم فتضعف المناعة ويسهل النزف، ولهذا تُجرى تحاليل الدم قبل الجلسات وأثناء العلاج. وأي أثر في اليدين والقدمين يُذكر للفريق مبكراً، ولا يُترك حتى يشتدّ.',
    en: 'Its best-known effect is hand-foot syndrome: tingling, burning, redness, swelling, peeling and sometimes blisters or sores on the palms of the hands and soles of the feet. Other common effects include nausea and vomiting, loss of appetite, diarrhoea or constipation, tiredness and dizziness, hair loss, mouth sores, and harmless orange-red urine after the session. It lowers blood cells, so immunity weakens and bleeding comes easily, which is why blood tests are done before sessions and during treatment. Any effect on the hands and feet should be mentioned to the team early, rather than left until it worsens.'
  },
  warning: {
    ar: 'أثناء التنقيط أخبر الممرّض فوراً عند: احمرار الوجه، أو ضيق الصدر، أو ألم الظهر، أو قشعريرة وحمّى، أو صداع، أو صعوبة في التنفّس أو البلع، أو تورّم الوجه أو العينين أو الشفتين أو الحلق، أو شرى وحكّة، فهذه علامات تفاعل التسريب. وبعد الجلسة اتصل بالفريق فوراً عند حرارة سبعة وثلاثين ونصف درجة أو أكثر أو أي علامة عدوى. واذهب إلى الطوارئ عند ألم في الصدر يمتدّ إلى الذراع أو الفكّ، أو ضيق نفس أو تورّم الساقين أو خفقان غير منتظم، أو نزف أو براز أسود أو قيء دم، أو قروح يدين وقدمين تمنعك من المشي أو الإمساك بالأشياء.',
    en: 'During the drip, tell the nurse at once about: facial flushing, chest tightness, back pain, chills and fever, headache, difficulty breathing or swallowing, swelling of the face, eyes, lips or throat, or hives and itching, which are signs of an infusion reaction. After the session, call the team at once with a temperature of thirty-seven and a half degrees or more or any sign of infection. Go to the emergency department for chest pain spreading to the arm or jaw, breathlessness, swollen legs or an irregular heartbeat, bleeding, black stools or vomiting blood, or sores on the hands and feet that stop you walking or holding things.'
  },
  interact: {
    ar: 'تذكر مدلاين بلس أدوية يجب إخبار الطبيب بها: السيكلوفوسفاميد، وأدوية الفصيلة نفسها كالدونوروبيسين والإبيروبيسين والإيداروبيسين والميتوكسانترون، والباكليتاكسيل، والتراستوزوماب، والفيراباميل. وأخبره بأي أنثراسيكلين أخذته سابقاً، ولو في علاج قديم. ولا لقاحات حيّة أثناء العلاج وحتى سنة بعده بحسب النشرة البريطانية. وأخبر الفريق بكل ما تتناوله من أدوية بوصفة أو بلا وصفة، ومن فيتامينات وأعشاب ومكمّلات، ومن يتعالج من فيروس نقص المناعة يذكر أدويته كلها.',
    en: 'MedlinePlus lists medicines you must tell the doctor about: cyclophosphamide, drugs of the same class such as daunorubicin, epirubicin, idarubicin and mitoxantrone, paclitaxel, trastuzumab and verapamil. Tell the doctor about any anthracycline you have had before, even in an old treatment. No live vaccines during treatment and for up to a year afterwards according to the British leaflet. Tell the team about everything you take, prescription or not, including vitamins, herbs and supplements, and anyone being treated for HIV should mention all their medicines.'
  },
  avoid: {
    ar: 'لا يُعطى لمن أصابته حساسية منه. ويُخبَر الطبيب بأي مرض قلب أو علاج إشعاعي سابق على الصدر، وبأي مرض في الكبد لأنه قد يستلزم تعديلاً. وهو قد يؤذي الجنين، فتتجنّب المرأة الحمل أثناء العلاج ولثمانية أشهر بعده، ويتجنّب الرجل أن تحمل شريكته أثناء العلاج ولستّة أشهر بعده، بحسب النشرة البريطانية، ويستعمل كلاهما وسيلة منع حمل فعّالة. ولا رضاعة أثناء العلاج. ويُفحص القلب بتخطيط وصورة بالموجات الصوتية قبل العلاج وأثناءه.',
    en: 'It is not given to anyone who has had an allergy to it. The doctor must be told about any heart disease or previous radiotherapy to the chest, and about any liver disease, as this may need an adjustment. It may harm an unborn baby, so a woman avoids pregnancy during treatment and for eight months afterwards, and a man avoids his partner becoming pregnant during treatment and for six months afterwards, according to the British leaflet, and both use effective contraception. No breastfeeding during treatment. The heart is checked with an ECG and an ultrasound scan before and during treatment.'
  },
  updated: '2026-09-11',
  src: [
    'https://medlineplus.gov/druginfo/meds/a612001.html',
    'https://www.cancerresearchuk.org/about-cancer/treatment/drugs/liposomal-doxorubicin'
  ]
};

RX_BODY['daunorubicin'] = {
  what: {
    ar: 'الدونوروبيسين دواء كيميائي من فصيلة الأنثراسيكلينات، شقيق الدوكسوروبيسين في العائلة والتحذيرات. يُعطى في الوريد داخل المستشفى فقط، وتنصّ النشرة على أن يُعطى تحت إشراف طبيب متمرّس في أدوية السرطان، عبر خطّ مركزي أو قنية في الذراع. ولونه أحمر، فيحمرّ البول بعده ليوم أو يومين دون ضرر. ولأنه قد يُتلف عضلة القلب، يُفحص القلب بتخطيط وصورة بالموجات الصوتية قبل البدء، ويُسأل المريض عن أي دواء من هذه الفصيلة أخذه سابقاً.',
    en: 'Daunorubicin is a chemotherapy drug from the anthracycline class, a sibling of doxorubicin in family and warnings. It is given into a vein in hospital only, and the label states it must be given under the supervision of a doctor experienced in cancer drugs, through a central line or a cannula in the arm. It is red, so the urine turns red for a day or two afterwards without harm. Because it can damage the heart muscle, the heart is checked with an ECG and an ultrasound scan before starting, and the patient is asked about any drug of this class received before.'
  },
  why: {
    ar: 'يُستعمل في نوعين من ابيضاض الدم: ابيضاض الدم النقوي الحادّ وابيضاض الدم اللمفاوي الحادّ، ويُعطى دائماً تقريباً مع أدوية كيميائية أخرى. وأشهر خططه في ابيضاض الدم النقوي الحادّ جمعه مع السيتارابين، وتُعطى هذه الخطّة عادةً في المستشفى لإحداث الهدأة، أي إزالة الخلايا الخبيثة من الدم والنخاع قدر الإمكان. وتحديد الخطّة ومراحلها قرار طبيب أمراض الدم بحسب نوع ابيضاض الدم وعمر المريض وحالة قلبه وكليتيه وكبده.',
    en: 'It is used in two types of leukaemia, acute myeloid leukaemia and acute lymphoblastic leukaemia, and is almost always given with other chemotherapy drugs. Its best-known plan in acute myeloid leukaemia combines it with cytarabine, usually given in hospital to bring about remission, meaning clearing the malignant cells from the blood and marrow as far as possible. Deciding the plan and its stages is the decision of the haematologist according to the type of leukaemia, the age of the patient and the state of the heart, kidneys and liver.'
  },
  how: {
    ar: 'مثل بقية الأنثراسيكلينات، يوقف الدونوروبيسين نموّ الخلايا السرطانية أو يبطئه بتعطيل قدرتها على نسخ حمضها النووي والانقسام، فتموت الخلايا الخبيثة التي تملأ النخاع. ولأنه يضرب الخلايا السريعة الانقسام، يصيب معها نخاع العظم السليم فتهبط كريات الدم هبوطاً شديداً، وبطانة الفم والأمعاء فتظهر التقرّحات والإسهال، وبصيلات الشعر فيتساقط. أما القلب فتتأثّر عضلته بهذه الفصيلة تأثّراً خاصّاً قد يظهر أثناء العلاج أو بعده بأشهر أو سنوات.',
    en: 'Like the other anthracyclines, daunorubicin stops or slows the growth of cancer cells by disrupting their ability to copy their DNA and divide, so the malignant cells that fill the marrow die. Because it hits rapidly dividing cells, it also affects the healthy bone marrow, so blood cells fall severely, the lining of the mouth and gut, so sores and diarrhoea appear, and the hair follicles, so hair falls out. The heart muscle is affected by this class in a particular way that may appear during treatment or months or years afterwards.'
  },
  effects: {
    ar: 'من آثاره الشائعة: غثيان وقيء، وتقرّحات في الفم والحلق، وإسهال، وألم في البطن، وتساقط الشعر، واحمرار البول، وتغيّرات في الجلد. وأهمّ أثر هبوط كريات الدم الشديد، وهو أثر متوقَّع في علاج ابيضاض الدم: فتضعف المناعة وتكثر العدوى، ويظهر فقر الدم بالشحوب وضيق النفس، ويسهل النزف والتكدّم لقلّة الصفائح. ولهذا تُجرى تحاليل الدم بانتظام أثناء العلاج. وتذكر النشرة أنه يرفع خطر سرطانات ثانوية لاحقاً.',
    en: 'Its common effects include nausea and vomiting, mouth and throat sores, diarrhoea, stomach pain, hair loss, red urine and skin changes. The most important effect is a severe fall in blood cells, an expected effect in leukaemia treatment: immunity weakens and infections become frequent, anaemia shows as pallor and breathlessness, and bleeding and bruising come easily from low platelets. That is why blood tests are done regularly during treatment. The label notes that it raises the risk of later secondary cancers.'
  },
  warning: {
    ar: 'أثناء الحقن أخبر الممرّض فوراً عند احمرار أو ألم أو تورّم أو حرقة أو لسع في موضعه، فتسرّبه تحت الجلد يُتلف الأنسجة. واتصل بالفريق فوراً عند حرارة سبعة وثلاثين ونصف درجة أو أكثر أو أقلّ من ستّ وثلاثين، أو قشعريرة أو التهاب حلق أو سعال. واذهب إلى الطوارئ عند: ضيق نفس، أو ألم في الصدر، أو تورّم اليدين أو القدمين أو الساقين، أو خفقان غير منتظم، ولو بعد انتهاء العلاج بفترة طويلة؛ أو صعوبة في التنفّس أو البلع مع شرى؛ أو نزف أو تكدّم غير معتاد؛ أو نزف من الشرج مع انتفاخ البطن.',
    en: 'During the injection, tell the nurse at once about redness, pain, swelling, burning or stinging at the site, because leakage under the skin damages the tissue. Call the team at once with a temperature of thirty-seven and a half degrees or more or below thirty-six, or chills, a sore throat or a cough. Go to the emergency department for: breathlessness, chest pain, swelling of the hands, feet or legs, or an irregular heartbeat, even long after treatment has ended; difficulty breathing or swallowing with hives; unusual bleeding or bruising; or bleeding from the back passage with a swollen abdomen.'
  },
  interact: {
    ar: 'أخبر الطبيب بأي أنثراسيكلين أخذته سابقاً كالدوكسوروبيسين أو الإبيروبيسين أو الإيداروبيسين، ولو قبل سنوات. وأخبره إن كنت تأخذ السيكلوفوسفاميد أو تلقّيت التراستوزوماب، فالنشرة تطلب ذكرهما، وأخبره إن تلقّيت علاجاً إشعاعياً على الصدر. ولا لقاحات حيّة أثناء العلاج ولفترة بعده قد تصل سنة. وأخبر الفريق بكل ما تتناوله من أدوية وفيتامينات وأعشاب ومكمّلات، ولا تبدأ دواءً جديداً دون سؤالهم ما دمت تحت العلاج.',
    en: 'Tell the doctor about any anthracycline you have had before, such as doxorubicin, epirubicin or idarubicin, even years ago. Tell them if you are taking cyclophosphamide or have received trastuzumab, as the leaflet asks for both to be mentioned, and tell them if you have had radiotherapy to the chest. No live vaccines during treatment and for a period afterwards that may reach a year. Tell the team about all the medicines, vitamins, herbs and supplements you take, and do not start any new medicine without asking them while you are under treatment.'
  },
  avoid: {
    ar: 'لا يُعطى لمن أصابته حساسية منه. ويُخبَر الطبيب بأي مرض قلب أو علاج إشعاعي سابق على الصدر. ومن عنده مرض في الكلى أو الكبد يحتاج تعديلاً يقرّره الطبيب. وهو قد يؤذي الجنين، فيُتجنّب الحمل أثناء العلاج ولستّة أشهر على الأقل بعده بحسب النشرة البريطانية، ويستعمل الطرفان وسيلة منع حمل فعّالة. ولا رضاعة أثناء العلاج. ويُفحص القلب قبل البدء لأن النشرة تحذّر من أذى قلبي قد يظهر بعد انتهاء العلاج بسنوات.',
    en: 'It is not given to anyone who has had an allergy to it. The doctor must be told about any heart disease or previous radiotherapy to the chest. Anyone with kidney or liver disease needs an adjustment decided by the doctor. It may harm an unborn baby, so pregnancy is avoided during treatment and for at least six months afterwards according to the British leaflet, both partners use effective contraception. No breastfeeding during treatment. The heart is checked before starting, because the label warns of heart damage that may appear years after treatment ends.'
  },
  updated: '2026-09-11',
  src: [
    'https://medlineplus.gov/druginfo/meds/a682289.html',
    'https://www.cancerresearchuk.org/about-cancer/treatment/drugs/daunorubicin'
  ]
};

RX_BODY['bleomycin'] = {
  what: {
    ar: 'البليومايسين مضادّ حيوي في أصله، لكنه لا يُستعمل لعلاج أي عدوى، بل في علاج السرطان وحده. يُعطى بطرق عدّة بحسب الخطّة: حقناً في العضل، أو في الوريد عبر خطّ مركزي أو قنية، أو حقناً في الورم نفسه، أو داخل تجويف في الجسم كالمسافة المحيطة بالرئة. خطره الأبرز على الرئتين، ولهذا يُسأل المريض عن رئتيه قبل البدء وتُراقب أثناء العلاج، ويبقى عليه أن يخبر أي طبيب أو طبيب تخدير يعالجه لاحقاً بأنه تلقّى هذا الدواء.',
    en: 'Bleomycin is an antibiotic in origin, but it is not used to treat any infection, only to treat cancer. It is given in several ways depending on the plan: as an injection into a muscle, into a vein through a central line or cannula, injected into the tumour itself, or into a body cavity such as the space around the lung. Its main danger is to the lungs, which is why the patient is asked about their lungs before starting and monitored during treatment, and they must tell any doctor or anaesthetist who treats them later that they have received this drug.'
  },
  why: {
    ar: 'يُستعمل في سرطانات الرأس والعنق، ومنها سرطانات الفم والشفة والخدّ واللسان والحنك والحلق واللوزتين والجيوب، وفي سرطانات القضيب والخصيتين وعنق الرحم والفرج، وفي لمفوما هودجكن واللمفوما غير الهودجكنية ضمن خطط مع أدوية أخرى. ويُستعمل كذلك لعلاج الانصباب الجنبي الذي تسبّبه الأورام، أي تجمّع السوائل حول الرئة، حيث يُحقن في تجويف الصدر. وتذكر مدلاين بلس استعماله أيضاً في ساركوما كابوسي المرتبطة بالإيدز. واختياره قرار فريق الأورام.',
    en: 'It is used in head and neck cancers, including cancers of the mouth, lip, cheek, tongue, palate, throat, tonsils and sinuses, in cancers of the penis, testicles, cervix and vulva, and in Hodgkin and non-Hodgkin lymphoma within plans with other drugs. It is also used to treat pleural effusion caused by tumours, meaning fluid collecting around the lung, where it is injected into the chest cavity. MedlinePlus also mentions its use in AIDS-related Kaposi sarcoma. Choosing it is the decision of the oncology team.'
  },
  how: {
    ar: 'البليومايسين مضادّ حيوي في أصله، لكنه لا يُستعمل ضدّ الجراثيم، فمدلاين بلس تصفه بأنه لا يُستعمل إلا في العلاج الكيميائي. وتصفه النشرة البريطانية بأنه يُتلف الخلايا السريعة الانقسام كالخلايا السرطانية، فيبطئ نموّها أو يوقفه. ولأن بعض الأنسجة السليمة سريعة التجدّد أيضاً، تظهر آثاره في الجلد والشعر وبطانة الفم. أما الرئتان فموضع خطره الأبرز، إذ قد يُحدث فيهما التهاباً يتطوّر إلى تليّف. وحين يُحقن في تجويف الصدر لعلاج الانصباب الخبيث يكون الهدف منع السوائل من التجمّع حول الرئة من جديد.',
    en: 'Bleomycin is an antibiotic in origin, but it is not used against germs; MedlinePlus describes it as used only in chemotherapy. The British leaflet describes it as destroying rapidly dividing cells such as cancer cells, slowing or stopping their growth. Because some healthy tissues also renew quickly, its effects appear in the skin, hair and lining of the mouth. The lungs are its main point of danger, as it can inflame them in a way that progresses to scarring. When it is injected into the chest cavity to treat a malignant effusion, the aim is to stop fluid collecting around the lung again.'
  },
  effects: {
    ar: 'من آثاره الشائعة: تغيّرات في الجلد كالاحمرار والفقاعات والألم عند اللمس والتسمّك والتورّم، واسمرار لون الجلد، وطفح، وتساقط الشعر بما فيه الرموش والحواجب، وتقرّحات في الفم واللسان، وقيء وغثيان، وفقدان الشهية ونقص الوزن. وتغيّرات الرئة من آثاره المعروفة: سعال وصعوبة في التنفّس والتهاب رئوي، وقد يتطوّر ذلك إلى تليّف، وخطره أعلى عند كبار السن ومع المقادير الكبيرة بحسب النشرة. وقد تحدث تفاعلات تحسّسية شديدة بعد أول جرعة أو ثانيها.',
    en: 'Its common effects include skin changes such as redness, blistering, tenderness, thickening and swelling, darkening of the skin, rash, hair loss including eyelashes and eyebrows, mouth and tongue sores, vomiting and nausea, and loss of appetite and weight. Lung changes are among its known effects: cough, difficulty breathing and pneumonitis, which may progress to scarring, and the risk is higher in older people and with large amounts according to the label. Severe allergic reactions may occur after the first or second dose.'
  },
  warning: {
    ar: 'اتصل بالفريق فوراً أو اذهب إلى الطوارئ عند: ضيق نفس مفاجئ أو تغيّر في التنفّس، أو صفير، أو سعال مع حمّى وقشعريرة، فهذه علامات أذى الرئة. واتصل فوراً عند حرارة سبعة وثلاثين ونصف درجة أو أكثر أو أقلّ من ستّ وثلاثين. واذهب إلى الطوارئ عند: خدر أو ضعف مفاجئ في الوجه أو الذراع أو الساق، أو ارتباك مفاجئ أو صعوبة في الكلام أو الفهم، أو دوخة مفاجئة وفقدان التوازن، أو صداع شديد، أو ألم في الصدر؛ أو طفح مع ضيق نفس وتورّم الوجه؛ أو ألم وتورّم في الساق؛ أو قلّة واضحة في البول.',
    en: 'Call the team at once or go to the emergency department for: sudden breathlessness or a change in breathing, wheezing, or a cough with fever and chills, which are signs of lung damage. Call at once with a temperature of thirty-seven and a half degrees or more or below thirty-six. Go to the emergency department for: sudden numbness or weakness of the face, arm or leg, sudden confusion or difficulty speaking or understanding, sudden dizziness and loss of balance, a severe headache, or chest pain; a rash with breathlessness and facial swelling; pain and swelling in a leg; or a clear decrease in urine.'
  },
  interact: {
    ar: 'أهمّ ما يحمله المريض معه: أن يخبر كل طبيب وطبيب أسنان وجرّاح وطبيب تخدير بأنه تلقّى البليومايسين، قبل أي عملية أو تخدير أو إعطاء أكسجين، فالنشرة البريطانية تنصّ على ذلك صراحة لأن رئتيه قد تكونان أكثر حساسية. وأخبر الفريق بكل ما تتناوله من أدوية بوصفة أو بلا وصفة، ومن فيتامينات وأعشاب ومكمّلات، فقد يراقبك الطبيب لآثار جانبية أشدّ مع بعضها. ولا لقاحات حيّة أثناء العلاج وحتى سنة بعده بحسب النشرة البريطانية.',
    en: 'The most important thing the patient carries with them: telling every doctor, dentist, surgeon and anaesthetist that they have received bleomycin, before any operation, anaesthetic or oxygen treatment, as the British leaflet explicitly states, because their lungs may be more sensitive. Tell the team about everything you take, prescription or not, including vitamins, herbs and supplements, as the doctor may watch you for more severe side effects with some of them. No live vaccines during treatment and for up to a year afterwards according to the British leaflet.'
  },
  avoid: {
    ar: 'لا يُعطى لمن أصابته حساسية منه. ويُخبَر الطبيب بأي مرض رئوي سابق، لأن النشرة تحذّر من أذى رئوي شديد قد يهدّد الحياة، وخطره أعلى عند كبار السن. ومن عنده مرض في الكلى عليه أن يخبر الطبيب. وهو قد يؤذي الجنين، فيُتجنّب الحمل أثناء العلاج ولستّة أشهر على الأقل بعده بحسب النشرة البريطانية، وتُناقش وسائل منع الحمل وخيارات حفظ الخصوبة قبل البدء. ولا يُنصح بالرضاعة أثناء العلاج. وقبل أي جراحة، ولو جراحة أسنان، أخبر الجرّاح بأنك تأخذه أو أخذته.',
    en: 'It is not given to anyone who has had an allergy to it. The doctor must be told about any previous lung disease, because the label warns of severe lung damage that can be life-threatening, with a higher risk in older people. Anyone with kidney disease must tell the doctor. It may harm an unborn baby, so pregnancy is avoided during treatment and for at least six months afterwards according to the British leaflet, and contraception and fertility preservation options are discussed before starting. Breastfeeding is not recommended during treatment. Before any surgery, even dental surgery, tell the surgeon that you are taking or have taken it.'
  },
  updated: '2026-09-11',
  src: [
    'https://medlineplus.gov/druginfo/meds/a682125.html',
    'https://www.cancerresearchuk.org/about-cancer/treatment/drugs/bleomycin'
  ]
};
